Let $E$ be an elementary abelian 2-group of rank $r$.
Then
\begin{equation*}
    H^*(E,\mathbb F_2)\simeq\mathbb F_2[x_1,\dots,x_r]
\end{equation*}
for $\deg(x_i)=1$ for $1\leq i\leq r$.

\label{negideal}
    Let $E$ be an elementary abelian 2-group of rank $n$.
    The negligible ideal $I(E,\mathbb F_2)$ over $\mathbb Q$ is generated by elements of the form
    \begin{equation*}
        \{x_ix_j^2+x_i^2x_j:1\leq i\leq j\leq n\}.
    \end{equation*}

\label{elem ab 2-group vanishing}
Let $E$ be an elementary abelian 2-group of rank $r$.
An element $p(x_1,\dots,x_r)\in H^d(E,\mathbb F_2)$ is negligible if and only if it vanishes whenever the coordinates are in $\mathbb{F}_2$.

\label{detect on elem ab}
Let $G$ be a finite group and $F$ a field.
The class $u\in H^*(G,\mathbb{F}_p)$ is eventually negligible over $F$ if and only if the restriction of $u$ to each elementary abelian $p$-subgroup is eventually negligible.

\label{quillen-venkov}
Let $G$ be a finite group.
The class $u\in H^*(G,\mathbb F_2)$ is eventually negligible over $\mathbb Q$ if and only if the restriction of $u$ to each elementary abelian 2-subgroup is negligible.

\label{half conjecture}
Let $H\subset G$.
Then the ring map
\begin{equation*}
    \text{res}:H^*(G,\mathbb{F}_p)\to H^*(H,\mathbb{F}_p)
\end{equation*}
sends negligible elements to negligible elements.

\label{lemma:corestriction}
Let $H\subset G$ be a subgroup of a finite group $G$.
Denote by
\begin{equation*}
    \text{cor}^d:H^d(H,\mathbb{F}_p)\to H^d(G,\mathbb{F}_p)
\end{equation*}
the degree $d$ corestriction (or transfer) map.
If $u\in H^d(H,\mathbb{F}_p)$ is negligible over $F$, then $\text{cor}^d(u)$ is negligible over $F$ in $H^d(G,\mathbb{F}_p)$.

Let $K=F(V)^G$ for $V$ a finite-dimensional faithful $F$-representation of $G$.
Since $H$ is a subgroup of $G$, $V$ is likewise a faithful $F$-representation of $H$.
Define $K_H=F(V)^H$.
We build the following commutative square.
\begin{equation*}
\begin{tikzcd}
    H^d(H,\mathbb{F}_p)\arrow{r}{\text{cor}^d}\arrow{d}{\text{inf}_H} &H^d(G,\mathbb{F}_p)\arrow{d}{\text{inf}} \\
    H^d(K_H,\mathbb{F}_p)\arrow{r}{\text{cor}^d} &H^d(K,\mathbb{F}_p)
\end{tikzcd}
\end{equation*}
By \cite[Proposition 2.1]{GM}, the kernel of these inflation maps are the negligible classes of $H^d(H,\mathbb{F}_p)$ and $H^d(G,\mathbb{F}_p)$ respectively.
Then $\text{inf}_H(u)=0$ implies that $\text{inf}(\text{cor}^d(u))=0$.
We conclude $\text{cor}^d(u)$ is negligible in $H^d(G,\mathbb{F}_p)$.

\label{intersection lemma}
Let $G$ be a finite group and $p$ be a prime integer.
Let $H\subset G$ be a subgroup for which $\gcd([G:H],p)=1$.
Then restriction is an injection of rings $H^*(G,\mathbb{F}_p)\to H^*(H,\mathbb{F}_p)$.
Further,
\begin{equation*}
    I(G,\mathbb{F}_p)=H^*(G,\mathbb{F}_p)\cap I(H,\mathbb{F}_p)
\end{equation*}
when $H^*(G,\mathbb{F}_p)$ is viewed as a subring of $H^*(H,\mathbb{F}_p)$.

\label{restriction les}
Let $\Gamma$ be a profinite group with character $x_i:\Gamma\to\mathbb Z/2 \mathbb Z$.
Denote the subgroup $\Gamma_i=\ker(x_i)$ of $\Gamma$.
Then the following exact sequence exists for $d\geq1$.
\[
\begin{tikzcd}[column sep=small]
    \cdots \arrow{r}{\mathrm{cor}^{d-1}}
    & H^{d-1}(\Gamma,\mathbb F_2)
      \arrow{r}{\cup x_i}
    & H^d(\Gamma,\mathbb F_2)
      \arrow{r}{\mathrm{res}}
    & H^d(\Gamma_i,\mathbb F_2)
      \arrow{r}{\mathrm{cor}^d}
    & H^d(\Gamma,\mathbb F_2)
      \arrow{r}{\cup x_i}
    & \cdots
\end{tikzcd}
\]

Endow the $\Gamma$-module exact sequence
\begin{equation*}
\begin{tikzcd}
    0\arrow{r} &\mathbb{F}_2\arrow{r} &\mathbb{F}_2\oplus\mathbb{F}_2\arrow{r} &\mathbb{F}_2\arrow{r} &0
\end{tikzcd}
\end{equation*}
with $\Gamma$-action on the middle term $\gamma\cdot(a,b)=(a+x_i(\gamma)\cdot b,b)$ for $a,b\in\mathbb F_2$ and $\gamma\in G$.
The middle term is isomorphic to $\text{Ind}_{\Gamma_i}^{\Gamma}(\mathbb Z/2\mathbb Z)$ as $\Gamma$-modules.
Shapiro's lemma applied to the induced long exact sequence completes the proof.
See \cite[Theorem 5]{Rusin} for another proof.

\label{nonneg-low-degree}
    There exist no non-trivial negligible classes of degree 1.
    In addition, there exist no non-trivial negligible classes of degree 2 over $\mathbb Q$.

\label{corestriction identity}
    For any two classes $a,b\in H^*(G,\mathbb F_2)$ in the cohomology ring, we have
    $$\operatorname{cor}(a\cdot \operatorname{res}(b))=\operatorname{cor}(a)\cdot b$$

\label{dihedralmodd}
Let $D_{2n}$ be the dihedral group of order $2n$ with $n$ an odd positive integer.
Then $I(D_{2n},\mathbb F_2)$ is trivial and the negligible ideal is radical.

\label{dihedralm2}
Let $D_{2n}$ be the dihedral group of order $2n$ with $n\equiv2$ (mod 4).
Then $I(D_{2n},\mathbb{F}_2)=N(D_{2n},\mathbb F_2)=\langle uv(u+v)\rangle=\langle vw\rangle$ is radical.

\label{dihedral even n}
    Let $D_{2n}$ be the dihedral group of order $2n$ with $n\equiv0$ (mod 4) an even positive integer.
    The eventually negligible ideal is $$N(D_{2n},\mathbb F_2) = \langle uw, vw\rangle.$$

\label{prop:uw-and-uw+vw-negligible}
Let $D_{2^n}$ be the dihedral group of order $2^n$.
For all $n\geq 3$,
\begin{equation*}
    I(D_{2^n},\mathbb{F}_2)=\langle uw, vw\rangle.
\end{equation*}

\label{dihedralm0}
    For $n \equiv 0$ (mod 4),
    \begin{equation*}
        I(D_{2n},\mathbb{F}_2)=\langle uw, vw\rangle.
    \end{equation*}
    The negligible ideal of $D_{2n}$ is radical.

\label{2x4}

    With indices as in Equation (\ref{elem ab indices}), and $1\leq i<i'\leq \ell$ and  $\ell+1\leq j<j'\leq m$,
    \begin{equation*}
        \langle  x_j, x_i^2x_{i'} + x_ix_{i'}^2, y_j^2y_{j'} + y_jy_{j'}^2, x_iy_j(x_i^2 + y_j)\rangle \subseteq N(G,\mathbb F_2).
    \end{equation*}

\label{lem32}
    Let $G$ be a finite abelian 2-group, and $x_i$, $x_j$ be distinct degree one generators of $H^*(G,\mathbb F_2)$. For all $k \geq 2$ and $\ell \geq 1$,
    \begin{equation*}
        x_i^k x_j^\ell = x_i^{k+\ell - 1}x_j
    \end{equation*}
    in $H^*(G,\mathbb F_2)/N(G,\mathbb F_2)$.

\label{Q8}
    The negligible ideal of $H^*(Q_{8}, \mathbb F_2)$ is
    \begin{equation*}
        I(Q_8,\mathbb F_2)=\langle a^2b, ac, bc\rangle.
    \end{equation*}

The negligible ideal of $H^*(Q_{2^n}, \mathbb F_2)$ for $n \geq 4$ is
    \begin{equation*}
        I(Q_{2^n},\mathbb F_2)=\langle a^3, ac, bc\rangle.
    \end{equation*}

\label{radicality-h3}
Let $H_3$ denote the finite Coxeter group of type $H_3$. Then the
mod-$2$ negligible ideal $I(H_3,\mathbb F_2)$ over $\mathbb Q$ is radical.
